const count = $json.iterations;

const items = [];

for (let i = 1; i <= count; i++) {
  items.push({
    json: {
      run: i
    }
  });
}

return items;

const items = $input.all();
const total = items.length;
const successCount = items.filter(i => i.json.status === 'success').length;
const errorCount = items.filter(i => i.json.status === 'error').length;

return [{
  json: {
    executionId: items[0]?.json.executionId ?? $execution.id,
    total,
    successCount,
    errorCount,
    allSucceeded: total === 20 && errorCount === 0 && successCount === 20
  }
}];

let review = $json.review ?? "";

// Markdown-Codefences entfernen
review = review.replace(/^```json\s*/i, "");
review = review.replace(/^```\s*/i, "");
review = review.replace(/\s*```$/i, "");

return [{
  json: {
    review
  }
}];
